mapper.select:
/* selectGroup - Lee JiSeob */
SELECT ADBK_GROUP_ESNTAL_NO, ADBK_GROUP_NM, ADBK_MENU_NO, POSESN_USER_ID, FRST_RGTR_ID, TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT, LAST_MDFR_ID, TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT
FROM SAB600 /* 주소록 그룹 */
WHERE POSESN_USER_ID = #{POSESN_USER_ID}
ORDER BY FRST_REG_DT DESC, ADBK_GROUP_NM

mapper.delete:

/* deleteGroup - Lee JiSeob */

DELETE FROM SAB600 /* 주소록 그룹 */

WHERE
	POSESN_USER_ID = #{POSESN_USER_ID}

mapper.insert:
/* insertGroup - Lee JiSeob */
MERGE INTO SAB600 /* 주소록 그룹 */ USING DUAL ON (TO_CHAR(ADBK_GROUP_ESNTAL_NO) = #{ADBK_GROUP_ESNTAL_NO})
WHEN MATCHED THEN
UPDATE SET ADBK_GROUP_NM = #{ADBK_GROUP_NM}, ADBK_MENU_NO = #{ADBK_MENU_NO}
WHEN NOT MATCHED THEN
INSERT ( ADBK_GROUP_ESNTAL_NO, ADBK_GROUP_NM, ADBK_MENU_NO, POSESN_USER_ID, FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_ID, LAST_MDFCN_DT ) VALUES ( SAB600_SQ01.NEXTVAL, #{ADBK_GROUP_NM}, '0', #{POSESN_USER_ID}, #{USER_ID}, SYSDATE, #{USER_ID}, SYSDATE )

mapper.delete:

/* deleteGroupName - Lee JiSeob */

DELETE FROM SAB600 /* 주소록 그룹 */

WHERE
	ADBK_GROUP_ESNTAL_NO = #{ADBK_GROUP_ESNTAL_NO}


/* deleteGroupPersons - Lee JiSeob */

DELETE FROM SAB610 /* 주소록 그룹 인원 */

WHERE
	ADBK_GROUP_ESNTAL_NO = #{ADBK_GROUP_ESNTAL_NO}

mapper.select:
/* selectGroupPerson - Lee JiSeob */
SELECT ADBK_GROUP_ESNTAL_NO, USER_NO, USER_SE_CD_NM, C##RG.DEC_B64(USER_NM_ENCPT) AS USER_NM_ENCPT, USER_ID, C##RG.DEC_B64(USER_MBL_TELNO_ENCPT) AS USER_MBL_TELNO_ENCPT, C##RG.DEC_B64(USER_EML_ADDR_ENCPT) AS USER_EML_ADDR_ENCPT, FRST_RGTR_ID, TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT, LAST_MDFR_ID, TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT, REGEXP_INSTR(USER_NO,'[^0-9]') AS IS_CHAR
FROM SAB610 /* 주소록 그룹 인원 */
WHERE ADBK_GROUP_ESNTAL_NO = #{ADBK_GROUP_ESNTAL_NO}
ORDER BY FRST_REG_DT DESC, USER_ID, CASE IS_CHAR WHEN 0 THEN TO_NUMBER(USER_NO) ELSE 0 END DESC

mapper.delete:

/* deleteGroupPerson - Lee JiSeob */

DELETE FROM SAB610 /* 주소록 그룹 인원 */

WHERE
	ADBK_GROUP_ESNTAL_NO = #{ADBK_GROUP_ESNTAL_NO}
	AND USER_NO = #{USER_NO}

mapper.select:
/* selectGroupPersons - Lee JiSeob */
SELECT DISTINCT USER_NO, USER_SE_CD_NM, C##RG.DEC_B64(USER_NM_ENCPT) AS USER_NM_ENCPT, USER_ID, C##RG.DEC_B64(USER_MBL_TELNO_ENCPT) AS USER_MBL_TELNO_ENCPT, C##RG.DEC_B64(USER_EML_ADDR_ENCPT) AS USER_EML_ADDR_ENCPT
FROM SAB610 /* 주소록 그룹 인원 */
WHERE ADBK_GROUP_ESNTAL_NO IN
#{no}
